97	  if (!rawFiles) return;
98	
99	  // If build target does not exist in project, use all files as input.
100	  // This is needed for transitive dependencies for apps -- where libs may not be buildable.
101	  const inputs = sourceProject.data.targets[buildTarget]
102	    ? getTargetInputs(readNxJson(), sourceProject, buildTarget).selfInputs
103	    : ['{projectRoot}/**/*'];
104	  if (ignoredFiles) {
105	    for (const pattern of ignoredFiles) {
106	      inputs.push(`!${pattern}`);
107	    }
108	  }
109	  const files = filterUsingGlobPatterns(
